class BankAccount {
    String accountHolder;
    double balance;

    void showBalance() {
        System.out.println("Account Holder: " + accountHolder + " | Balance: $" + balance);
    }
}

public class Main {
    public static void main(String[] args) {
        BankAccount acc = new BankAccount();
        acc.accountHolder = "Vikram";
        acc.balance = 1500.0;
        acc.showBalance();
    }
}

class Car {
    String model;
    int topSpeed;

    void displaySpecs() {
        System.out.println("Model: " + model + ", Top Speed: " + topSpeed + " km/h");
    }
}

public class Main {
    public static void main(String[] args) {
        Car c = new Car();
        c.model = "Tesla Model 3";
        c.topSpeed = 225;
        c.displaySpecs();
    }
}
